import{_ as t,a as n}from"./chunks/ugso_template_condition.B_NKCd7q.js";import{_ as r,o as s,c as i,a3 as a}from"./chunks/framework.BlfGB29P.js";const o="/assets/blocks-for-ha/blocks/de/ugso_template_time_window.png",l="/assets/blocks-for-ha/blocks/de/ugso_template_change.png",d="/assets/blocks-for-ha/blocks/de/ugso_entity_value.png",u="/assets/blocks-for-ha/blocks/de/ugso_entity_value_dynamic.png",c="/assets/blocks-for-ha/blocks/de/ugso_entity_snapshot.png",g="/assets/blocks-for-ha/blocks/de/ugso_automation_control.png",h="/assets/blocks-for-ha/blocks/de/ugso_app_control.png",m="/assets/blocks-for-ha/blocks/de/ugso_template_builder.png",p="/assets/blocks-for-ha/blocks/de/ugso_template_linebreak.png",b="/assets/blocks-for-ha/blocks/de/ugso_number_format.png",k="/assets/blocks-for-ha/blocks/de/ugso_template_conditional.png",x=JSON.parse('{"title":"Systemwerte und Template-Baukasten","description":"Gemeinsame Entitätswerte, App- und Automationssteuerung und verständliche Templates.","frontmatter":{"title":"Systemwerte und Template-Baukasten","description":"Gemeinsame Entitätswerte, App- und Automationssteuerung und verständliche Templates."},"headers":[],"relativePath":"projects/blocks-for-ha/system-template.md","filePath":"projects/blocks-for-ha/system-template.md","lastUpdated":1792857501000}'),f={name:"projects/blocks-for-ha/system-template.md"};function w(A,e,_,z,T,v){return s(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="systemwerte-und-template-baukasten" tabindex="-1">Systemwerte und Template-Baukasten <a class="header-anchor" href="#systemwerte-und-template-baukasten" aria-label="Permalink to &quot;Systemwerte und Template-Baukasten&quot;">​</a></h1><p>Seit <strong>0.1.62</strong>, vollständig in DE/EN/FR. Die neuen Systemblocks sind auch die Wertlieferanten für Templates. Vorhandene Text-, Mathematik- und Variablenblocks werden weiterverwendet.</p><p>Seit <strong>0.1.63</strong> hat Template direkte Werte-Andockpunkte in untereinander angeordneten Zeilen, ähnlich „Datei schreiben“ bei ioBroker. Alle Template-Bausteine sind ohne Zahnrad; die Eingänge passen zum jeweiligen Typ.</p><h2 id="zweckbezogene-templates-seit-0-1-64" tabindex="-1">Zweckbezogene Templates seit 0.1.64 <a class="header-anchor" href="#zweckbezogene-templates-seit-0-1-64" aria-label="Permalink to &quot;Zweckbezogene Templates seit 0.1.64&quot;">​</a></h2><p>Alle folgenden Bausteine stehen unter <strong>Templates</strong>, ohne Zahnrad. <strong>Text zusammenstellen</strong> erzeugt Text für Nachrichten; <strong>Uhrzeit im Zeitraum</strong> und <strong>Wertänderung prüfen</strong> liefern einen Logikwert und passen direkt an „Nur wenn“, „falls“, „und“ oder „oder“. <strong>Wert auswählen – falls/sonst</strong> hat einen wählbaren Ergebnistyp und dazu passende Andockpunkte.</p><h3 id="uhrzeit-im-zeitraum" tabindex="-1">Uhrzeit im Zeitraum <a class="header-anchor" href="#uhrzeit-im-zeitraum" aria-label="Permalink to &quot;Uhrzeit im Zeitraum&quot;">​</a></h3><p>Beginn und Ende als <code>HH:MM</code> oder <code>HH:MM:SS</code> eingeben. Die aktuelle Ortszeit von HA wird geprüft: <strong>ab einschließlich</strong>, <strong>bis ausschließlich</strong>. Mit 10:00 und 13:00 entspricht das deinem Beispiel <code>&#39;10:00:00&#39; &lt;= now().strftime(&#39;%H:%M:%S&#39;) &lt; &#39;13:00:00&#39;</code>. 22:00 bis 06:00 funktioniert über Mitternacht. Gleiche Grenzen ergeben falsch. Dieser Block ist eine Bedingung, kein Zeit-Auslöser.</p><p><img src="'+o+'" alt="Uhrzeit im Zeitraum"></p><h3 id="wertanderung-prufen" tabindex="-1">Wertänderung prüfen <a class="header-anchor" href="#wertanderung-prufen" aria-label="Permalink to &quot;Wertänderung prüfen&quot;">​</a></h3><p><strong>Anstieg über 10</strong>, <strong>Abfall über 20</strong> prüft <code>neuer Wert - alter Wert &gt; 10</code> oder <code>&lt; -20</code>. Die Abfallschwelle wird als positive Größe eingegeben. Genau +10 oder −20 erfüllt die Bedingung nicht.</p><p>„Alter Wert“ und „Neuer Wert“ dürfen leer bleiben: dann werden <code>trigger.from_state.state</code> und <code>trigger.to_state.state</code> benutzt. Das ist für Zustandsauslöser geeignet. Ohne Auslöser oder ohne alten Zustand ist das Ergebnis falsch; ebenso bei altem <code>unknown</code>, <code>unavailable</code> oder <code>none</code>. Alternativ passende Werte anschließen, etwa gespeicherte Variablen und System-Entitätswerte. Beide Werte werden wie im Beispiel mit <code>float(0)</code> umgewandelt: nicht numerischer Text zählt als 0. Leere neue Auslöserwerte zählen ebenfalls als 0. Wer das vermeiden möchte, muss den neuen Wert zusätzlich prüfen.</p><p><img src="'+l+'" alt="Wertänderung prüfen"></p><h3 id="eigener-jinja-code" tabindex="-1">Eigener Jinja-Code <a class="header-anchor" href="#eigener-jinja-code" aria-label="Permalink to &quot;Eigener Jinja-Code&quot;">​</a></h3><p><strong>Jinja – eigener Code</strong> nimmt eine vollständige Vorlage für einen Werteingang auf; <strong>Jinja – eigene Bedingung</strong> nimmt eine vollständige boolesche Vorlage auf. Auch mehrzeilige <code>{% if %}</code>, <code>{% set %}</code> und <code>{% else %}</code> bleiben unverändert erhalten. Für einen Teil von „Text zusammenstellen“ ist nur ein einzelner Ausdruck <code>{{ ... }}</code> geeignet; vollständige Anweisungsblöcke direkt am Ziel verwenden.</p><p><img src="'+t+'" alt="Eigener Code"><img src="'+n+'" alt="Eigene Bedingung"></p><p>Die bisher gleichwertigen Freicode-Einträge sind aus <strong>Jinja (experimentell)</strong> entfernt; sie stehen einmal unter <strong>Templates</strong>. Die experimentelle Kategorie behält den zerlegbaren Jinja-Baukasten. Dessen Teile bearbeiten Jinja-Ausdrücke; sie sind keine zusätzlichen HA-Aktionen. Alte Projekt-Blöcke und importierter Originalcode bleiben lesbar.</p><p>Unter <strong>System</strong> heißen die Steuerblöcke <strong>App steuern</strong> und <strong>Automation steuern</strong>. Seit 0.1.64 sind sie zweizeilig wie „Instanz steuern“ in ioBroker: Auswahl oben, „Aktion“ darunter. HA-Apps und Automation-Entitäten ersetzen dort ioBroker-Instanzen.</p><h2 id="system" tabindex="-1">System <a class="header-anchor" href="#system" aria-label="Permalink to &quot;System&quot;">​</a></h2><p>Änderungen im Zahnrad wirken sofort auf den Hauptblock: Hinzufügen zeigt die Zeile, Entfernen blendet sie aus und passt die Größe an, auch bei geöffnetem Popup.</p><table tabindex="0"><thead><tr><th>Baustein</th><th>Verwendung</th></tr></thead><tbody><tr><td>Entitäts-ID</td><td>Entität auswählen und ihre ID an einen anderen Block anschließen.</td></tr><tr><td>Wert von Entität</td><td>Feste HA-Auswahl: Zustand, Name, Einheit, Attribut, zuletzt geändert oder aktualisiert.</td></tr><tr><td>Wert von Entitäts-ID</td><td>Eine ID aus einem Entitäts-ID-, Text- oder Variablenblock anschließen.</td></tr><tr><td>Einmal lesen in Variable</td><td>Momentaufnahme speichern, danach die enthaltenen Aktionen ausführen. Kein Auslöser. Die Variable ist auch für folgende HA-Schritte verfügbar.</td></tr><tr><td>App steuern</td><td>Starten, stoppen oder neu starten. Installierte Apps über Supervisor auswählen oder Kennung manuell eingeben.</td></tr><tr><td>Automation steuern</td><td>Aktivieren, deaktivieren, umschalten oder jetzt ausführen.</td></tr></tbody></table><p><img src="'+d+'" alt="Entitätswert"><img src="'+u+'" alt="Dynamischer Entitätswert"><img src="'+c+'" alt="Momentaufnahme"><img src="'+g+'" alt="Automation steuern"><img src="'+h+'" alt="App steuern"></p><p><strong>Attribut</strong> wählen und den Attributnamen eingeben; die passende Zeile erscheint automatisch. Zustände sind häufig Text. Vor Rechnungen bei Bedarf <strong>Konvertierung → nach Zahl</strong> verwenden. Fehlende Attribute und Zeitstempel liefern <code>none</code>; ein fehlender Zustand liefert HA-typisch <code>unknown</code>. <strong>Ersatzwert</strong> kann diese Werte auffangen.</p><p>Bei <strong>Automation steuern</strong> ergänzt das Zahnrad: <strong>Entitäts-ID anschließen</strong>, <strong>Bedingungen berücksichtigen</strong> und <strong>Laufende Aktionen stoppen</strong>. Die angeschlossene ID ersetzt die feste Auswahl. Bedingungen gelten für „jetzt ausführen“, Stoppen gilt für „deaktivieren“. Ohne explizite Option verwendet HA seine Defaults: Ausführen überspringt Bedingungen, Deaktivieren stoppt laufende Aktionen. Aktivieren startet die Aktionen nicht, sondern schaltet die Auslöser frei.</p><p><strong>App steuern</strong> benötigt Supervisor und Administratorrechte. Die App erhält lesenden Supervisor-Zugriff für die Auswahlliste; Start/Stop/Neustart erfolgen erst durch die exportierte Automation in HA. Ohne Supervisor bleibt die Kennung manuell bearbeitbar, die Aktion steht dort jedoch nicht zur Verfügung. Export: <code>hassio.app_start</code>, <code>hassio.app_stop</code>, <code>hassio.app_restart</code> mit <code>data.app</code>.</p><h2 id="template-zusammenstecken" tabindex="-1">Template zusammenstecken <a class="header-anchor" href="#template-zusammenstecken" aria-label="Permalink to &quot;Template zusammenstecken&quot;">​</a></h2><ol><li><strong>Templates → Text zusammenstellen</strong> in einen Texteingang stecken, etwa „Nachricht“.</li><li>Normalen <strong>Text</strong> direkt an <strong>Teil 1</strong> anschließen.</li><li>Einen <strong>Entitätswert aus System</strong> oder ein <strong>Zahlenformat</strong> direkt an <strong>Teil 2</strong> anschließen.</li><li>Wird der letzte Eingang belegt, erscheint automatisch ein weiterer Andockpunkt. Die Reihenfolge von oben nach unten ist die Ausgabereihenfolge. Leere Eingänge werden ausgelassen und behalten ihre Position für Rückgängig/Wiederholen.</li></ol><p>Beispiel: Text <code>Temperatur: </code> → Entitätswert <code>sensor.temperatur</code> über <strong>Zahlenformat</strong> mit Mathematik-Zahl <code>1</code> als Nachkommastellen → Text <code> °C</code>. Ergebnis beispielsweise <code>Temperatur: 21.6 °C</code>.</p><p><img src="'+m+'" alt="Template"><img src="'+p+'" alt="Zeilenumbruch als Wert"><img src="'+b+'" alt="Zahlenformat"><img src="'+k+'" alt="Bedingte Ausgabe"></p><table tabindex="0"><thead><tr><th>Ergänzung</th><th>Bedeutung</th></tr></thead><tbody><tr><td>Zahlenformat</td><td>0–10 Nachkommastellen, immer mit Dezimalpunkt. Mathematik-Zahl für die Anzahl verwenden. Ersatzwert direkt am optionalen Werteingang anschließen; sonst leerer Text bei ungültiger Zahl.</td></tr><tr><td>Wert sonst</td><td>Ersatz für <code>unknown</code>, <code>unavailable</code>, <code>none</code> und leeren Text. <code>0</code> und <code>false</code> bleiben erhalten.</td></tr><tr><td>Zeilenumbruch</td><td>Neue Zeile an dieser Stelle.</td></tr><tr><td>Wert auswählen – falls/sonst</td><td>Ergebnistyp wählen: Wert, Text, Zahl oder Logikwert. An „falls“ eine boolesche Bedingung anschließen; an „dann“ und „sonst“ passende Werte. Für mehrere Textteile ein „Text zusammenstellen“ anschließen. Leere Zweige ergeben bei Wert/Text leeren Text; Zahl/Logikwert benötigen beide Zweige.</td></tr></tbody></table><p>Formatierung wird direkt um den betroffenen Wert gesteckt. Text, Zahlen, Entitätswerte, Zeilenumbruch und bedingte Werte verwenden Werteanschlüsse; „falls“ akzeptiert nur boolesche Blocks. Aktionsketten passen nicht in diese Eingänge. Jinja-Zeichen in einem normalen Textblock bleiben wörtlicher Text. Ältere Ausgeben-Ketten werden beim Laden im Editor automatisch in direkte Werte umgewandelt, einschließlich Zweigen und deaktivierten Teilen. Die alten Blocktypen bleiben für die Projektkompatibilität lesbar, erscheinen aber nicht mehr im Menü.</p><p><strong>Rechtsklick → Template-Vorschau / Jinja</strong> zeigt den erzeugten Code und lässt HA mit aktuellen Werten rendern. Dies ist eine Momentaufnahme, führt keine Aktionen aus und funktioniert nur bei erreichbarer HA-Verbindung. Ohne Verbindung wird die Vorschau ausdrücklich als nicht verfügbar angezeigt. Zugangsdaten bleiben auf dem Server. Beim Projekt-JSON bleiben Blocks, Verbindungen und Zahnradoptionen erhalten. YAML enthält natives Jinja; beim YAML-Import kann es wieder als freier Templateblock erscheinen. HA kann reine Zahlen oder Listen aus Templateergebnissen als native Werte interpretieren.</p><p>Referenzen: <a href="https://www.home-assistant.io/docs/automation/automation_integration_actions/" target="_blank" rel="noreferrer">HA-Automationsaktionen</a>, <a href="https://www.home-assistant.io/integrations/hassio/" target="_blank" rel="noreferrer">Supervisor</a>, <a href="https://www.home-assistant.io/docs/templating/" target="_blank" rel="noreferrer">Jinja in HA</a>.</p>',32)])])}const B=r(f,[["render",w]]);export{x as __pageData,B as default};
